    nav=''.join(f'<a href="{p}"'+(' aria-current="page"' if p==path else '')+f'>{n}</a>' for n,p in [('Services','/services/'),('Local codes','/local-codes/'),('Guides','/guides/'),('FAQ','/faq/')])
