edges=''.join(f'<svg class="edge-{side}" viewBox="0 0 225 500" aria-hidden="true">{vine}</svg>' for side in ['left','right'])
home=f'''<section class="hero dark"><p class="eyebrow">Overgrown property? You have a way forward.</p><h1><a class="button hero-button" href="/fix-my-violation/" data-request>Fix My Violation <span aria-hidden="true">↗</span></a></h1><p class="hero-sub">Got an overgrown property notice? Let’s get it cleared before your deadline.</p><a class="hero-call" href="tel:+18136712757">Or call 813-671-2757</a><p class="hero-note">Hillsborough · Pinellas · Manatee</p>{grass}{edges}</section><div class="service-strip"><div class="wrap"><span>✓ Overgrown-lot cleanup</span><span>✓ Before &amp; after photos</span><span>✓ Help understanding your next step</span></div></div><section class="section"><div class="wrap"><div class="section-head"><div><p class="eyebrow">Take it one step at a time</p><h2>A notice is stressful.<br>The next step can be simple.</h2></div><p>Start with the deadline. We handle the property cleanup; your local code officer confirms compliance.</p></div><div class="grid-3"><div class="step"><span class="number">01 /</span><h3>Show us the notice.</h3><p>Share the address, cited conditions and deadline. We’ll discuss the work and availability.</p></div><div class="step"><span class="number">02 /</span><h3>Get the property cleared.</h3><p>Mowing, bush hogging, brush clearing and removal, with a scope matched to your property.</p></div><div class="step"><span class="number">03 /</span><h3>Document the difference.</h3><p>Use before-and-after photos and your invoice to request reinspection and written closure.</p></div></div><div class="help-band"><p><strong>Deadline within 7 days?</strong>Call to discuss availability. An online request does not extend your deadline.</p>{PHONE}</div></div></section><section class="section local-section"><div class="wrap local-grid"><div class="local-intro"><p class="eyebrow">Know which rules apply</p><h2>Same overgrowth.<br>Different local codes.</h2><p>Your mailing address doesn’t always identify your jurisdiction. Start with the government named on your notice.</p><a href="/local-codes/">Find your local code guide ↗</a></div><div class="jurisdiction-links">'''+''.join(f'<a href="/local-codes/{g["slug"]}/"><div>{g["label"]}<span>{g["county"]}</span></div><b aria-hidden="true">↗</b></a>' for g in LOCAL)+'''<a href="/local-codes/"><div>Not sure?<span>How to identify your jurisdiction</span></div><b aria-hidden="true">↗</b></a></div></div></section><section class="section"><div class="wrap services-layout"><div><p class="eyebrow">From overgrown to maintained</p><h2>The cleanup<br>your lot needs.</h2><p class="muted">One yard or a larger vacant parcel: tell us what’s growing, what needs to go and what the notice requires.</p><a href="/services/">Explore cleanup services ↗</a></div><div class="service-list">'''+serviceitems()+'''</div></div></section><section class="section dark"><div class="wrap"><div class="section-head"><div><p class="eyebrow">Plain-English answers</p><h2>Understand the notice.<br>Know your next move.</h2></div><p>Practical guides with official sources, from the first inspection to getting the case closed.</p></div><div class="guide-grid">'''+''.join(card(GUIDES[i]) for i in [1,2,7])+'''</div><p style-placeholder=""><a href="/guides/">Browse all owner guides ↗</a></p></div></section><section class="section"><div class="wrap"><p class="eyebrow">Rooted in Tampa Bay</p><h2>Three counties. A lot to reclaim.</h2>'''
areahtml='<div class="area-block"><div><h3>Hillsborough</h3><p>Tampa, Brandon, Riverview, Plant City, Thonotosassa and Wimauma.</p></div><div><h3>Pinellas</h3><p>St. Petersburg, Pinellas Park, Clearwater, Largo, Seminole, Lealman and the Pinellas beach towns.</p></div><div><h3>Manatee</h3><p>Bradenton, Palmetto, Parrish and Ellenton.</p></div></div>'
home+=areahtml+'</div></section><section class="section local-section"><div class="wrap narrow"><p class="eyebrow">A few common questions</p><h2>Let’s clear this up.</h2>'+faqitems(FAQ[:3])+'<p><a href="/faq/">All 30 questions &amp; answers ↗</a></p></div></section>'+endcta()
page('/','Tampa Bay Overgrown-Property Cleanup & Code Violation Help','Received an overgrown-property notice in Tampa Bay? Get mowing, brush clearing and cleanup help in Hillsborough, Pinellas and Manatee, plus local code guides.',home.replace(' style-placeholder=""',''))
# Full guides, with visible references matching structured data.
for base,data,parent in [('/guides/',GUIDES,('Guides','/guides/')),('/local-codes/',LOCAL,('Local codes','/local-codes/'))]:
    for g in data:
        path=base+g['slug']+'/'
        sourcehtml='<section class="sources" id="sources"><h2>Official sources</h2><ol>'+''.join(f'<li><a href="{S[k][1]}">{S[k][0]}</a></li>' for k in g['sources'])+'</ol><p class="small">Reviewed October 7, 2026. Laws and agency procedures can change. Confirm the current section and instructions for your case.</p></section>'
        body=intro(g['title'],g['intro'],g['label'],parent,True)+'<div class="wrap article-layout"><article class="article-content"><div class="answer-box"><p class="eyebrow">The short answer</p><p>'+g['answer']+'</p></div>'+''.join(f'<section aria-labelledby="{id}"><h2 id="{id}">{title}</h2>{copy}</section>' for id,title,copy in g['sections'])+sourcehtml+f'<p class="legal">{LEGAL}</p><div class="related"><a href="/guides/proving-compliance/">Prove compliance</a><a href="/guides/request-an-extension/">Request more time</a><a href="/faq/">Frequently asked questions</a></div></article><aside class="side-nav"><h2>In this guide</h2><ul>'+''.join(f'<li><a href="#{id}">{title}</a></li>' for id,title,_ in g['sections'])+'<li><a href="#sources">Official sources</a></li></ul><div class="side-cta dark"><h3>Need the property cleared?</h3><p>Share the notice and deadline. We’ll discuss the cleanup.</p>'+CTA+f'<a class="phone" href="tel:+18136712757">813-671-2757</a></div></aside></div>'+endcta()
        article={'@type':'Article','headline':g['title'],'description':g['description'],'datePublished':DATE,'dateModified':DATE,'author':{'@type':'Organization','name':'Fix My Violation','url':BASE+'/'},'publisher':{'@id':BASE+'/#business'},'mainEntityOfPage':BASE+path,'citation':[S[k][1] for k in g['sources']]}
        page(path,g['label']+': Tampa Bay Property Owner Guide',g['description'],body,[article],parent=parent)
page('/guides/','Tampa Bay Code Violation Guides for Property Owners','Understand overgrowth notices, deadlines, fines, hearings, liens and compliance. Plain-English Tampa Bay owner guides with official Florida sources.',intro('A clearer path through code enforcement.','Read the notice, identify the next deadline, and take the next step with confidence. These guides explain the process without promising a particular outcome.','Owner guides')+'<section class="section"><div class="wrap directory-list">'+''.join(card(g) for g in GUIDES)+'</div></section>'+endcta())
page('/local-codes/','Tampa Bay Overgrowth Codes by Jurisdiction','Compare overgrowth rules and enforcement processes in Tampa, Hillsborough, St. Petersburg, Clearwater, Pinellas, Bradenton and Manatee.',intro('Your notice. Your jurisdiction. Your rules.','A city mailing address is not proof that city rules apply. Use the issuing agency and parcel location to choose the correct guide.','Local codes',review=True)+'<section class="section"><div class="wrap"><div class="answer-box"><h2>Start with the issuing agency.</h2><p>Look at the notice’s letterhead, case number and cited ordinance. If the parcel is outside city limits, the county usually handles property-maintenance enforcement. Ask the listed officer to confirm jurisdiction when boundaries are unclear.</p><p>Plant City, Temple Terrace, Pinellas Park, Largo, Seminole, Palmetto and the beach municipalities may have their own rules. Do not substitute one of the county standards below for a municipal notice. Choose “Other/Not sure” on our request form if needed.</p></div><div class="directory-list">'+''.join(card(g,'/local-codes/') for g in LOCAL)+'</div><div class="legal">'+LEGAL+'</div></div></section>'+endcta())
page('/faq/','Tampa Bay Overgrown Yard & Code Enforcement FAQ','Answers to 30 questions about Tampa Bay overgrown yards, code notices, deadlines, fines, hearings, county mowing, liens and proving compliance.',intro('Real questions. Clear next steps.','Answers for owners dealing with overgrown-property notices in Hillsborough, Pinellas and Manatee counties. Always check the issuing agency and your own notice.','FAQ',review=True)+'<section class="section"><div class="wrap narrow">'+faqitems(FAQ)+f'<p class="legal">{LEGAL}</p></div></section>'+endcta(),[{'@type':'FAQPage','mainEntity':[{'@type':'Question','name':q,'acceptedAnswer':{'@type':'Answer','text':a}} for q,a,_,_ in FAQ]}])
page('/services/','Overgrown-Lot Cleanup Services in Tampa Bay','Emergency lot mowing, bush hogging, brush clearing, debris removal, before-and-after photos and recurring maintenance across three Tampa Bay counties.',intro('Reclaim the property. Take the next step.','Cleanup for overgrown yards and lots in Hillsborough, Pinellas and Manatee counties. Send the notice so we can discuss the work it calls for.','Cleanup services')+'<section class="section"><div class="wrap services-layout"><div><h2>Tell us what needs to change.</h2><p>Share the property address, approximate size, growth height, deadline and access details. Note fences, locked gates, soft ground, utilities or debris hidden in the growth.</p><p>We’ll discuss scope and availability before work is scheduled. An inquiry is not a confirmed booking or a guarantee of compliance.</p>'+CTA+'</div><div class="service-list">'+serviceitems()+'</div></div></section><section class="section local-section"><div class="wrap narrow"><h2>The job is more than cutting grass.</h2><p>A notice can include weeds, brush, trash and adjacent maintenance areas. Read every cited condition and ask the officer about unclear boundaries. Tell us if other violations appear on the same notice; our cleanup services may not address building, zoning or vehicle issues.</p><p>Vegetation removal may be restricted by tree protections, wetland rules or other requirements. Confirm permission before clearing protected areas. We do not determine legal property boundaries or issue permits.</p><h2>Finish with evidence.</h2><p>Our before-and-after photos help document the work. Send those photos and your invoice to the assigned officer with the case number and property address. Request reinspection and written case status. Cleanup alone does not cancel existing fines, liens or hearings.</p><a href="/guides/proving-compliance/">See the compliance checklist ↗</a></div></section><section class="section"><div class="wrap"><h2>Our Tampa Bay service area</h2>'+areahtml+'</div></section>'+endcta(),[{'@type':'Service','name':n,'serviceType':n,'description':d,'provider':{'@id':BASE+'/#business'},'areaServed':AREAS,'url':BASE+'/services/#'+s} for n,d,s in SERVICES])
# Form: all controls labelled; configuration gate prevents false submissions.
def field(name,label,type='text',required=False,full=False,hint='',autocomplete=None):
    return f'<div class="field{" full" if full else ""}"><label for="{name}">{label}'+(' *' if required else ' <span class="optional">(optional)</span>')+f'</label><input id="{name}" name="{name}" type="{type}"'+(' required' if required else '')+(f' autocomplete="{autocomplete}"' if autocomplete else '')+(' maxlength="500"' if type in ['text','email','tel'] else '')+(f' aria-describedby="{name}-hint"' if hint else '')+'>'+ (f'<p class="hint" id="{name}-hint">{hint}</p>' if hint else '')+'</div>'
def select(name,label,options,required=False):return f'<div class="field full"><label for="{name}">{label}'+(' *' if required else '')+f'</label><select id="{name}" name="{name}"'+(' required' if required else '')+'><option value="">Choose an option</option>'+''.join(f'<option>{e(o)}</option>' for o in options)+'</select></div>'
juris=['City of Tampa','Unincorporated Hillsborough','Temple Terrace','Plant City','St. Petersburg','Clearwater','Largo','Pinellas Park','Unincorporated Pinellas','Bradenton','Palmetto','Unincorporated Manatee','Other/Not sure']
stages=['Courtesy/warning notice','Notice of violation','Notice of hearing','Order/fines running','Lien','Not sure']
hidden=''.join(f'<input type="hidden" name="{n}" value="{v}">' for n,v in [('access_key',''),('subject','Overgrown-property cleanup request'),('from_name','Fix My Violation website'),('page_source','/fix-my-violation/'),('landing_page',''),('request_page','/fix-my-violation/')]+[(x,'') for x in ['utm_source','utm_medium','utm_campaign','utm_term','utm_content']])
form='<div class="wrap form-layout"><form class="lead-form" action="https://api.web3forms.com/submit" method="post" enctype="multipart/form-data">'+hidden+'<input type="checkbox" name="botcheck" tabindex="-1" hidden aria-hidden="true"><p class="required-note">* Required. No case number yet? You can still request help.</p><fieldset><legend>1. How can we reach you?</legend><div class="field-grid">'+field('name','Name',required=True,autocomplete='name')+field('phone','Phone','tel',True,autocomplete='tel')+field('email','Email','email',full=True,autocomplete='email')+'</div></fieldset><fieldset><legend>2. Tell us about the property.</legend><div class="field-grid">'+field('property_address','Property address',required=True,full=True,autocomplete='street-address')+select('jurisdiction','Jurisdiction',juris,True)+field('lot_size','Approximate lot size',hint='Square feet, acres or “not sure.”')+field('growth_height','Approximate growth height',hint='Inches, feet or “not sure.”')+'</div></fieldset><fieldset><legend>3. What does the notice say?</legend><div class="field-grid">'+field('case_number','Case/citation number',full=True)+select('notice_stage','Notice stage',stages)+field('compliance_deadline','Compliance deadline','date')+field('hearing_date','Hearing date, if known','date')+'</div><div class="form-urgency" role="status" aria-live="polite" hidden><p><strong data-urgency-text></strong> <a href="tel:+18136712757">Call 813-671-2757</a>. Contact the code officer separately about any extension.</p></div></fieldset><fieldset><legend>4. Anything else we should know?</legend><div class="field"><label for="message">Anything else? <span class="optional">(optional)</span></label><textarea id="message" name="message" maxlength="5000" rows="5" placeholder="Access instructions, locked gates, brush or debris, or questions about the cleanup…"></textarea></div></fieldset><p class="consent">By submitting, you ask Fix My Violation to contact you about this cleanup request. Submission does not schedule work, extend a deadline or notify the government. <a href="/privacy/">How we handle request information</a>.</p><div class="form-status" role="status" aria-live="polite" tabindex="-1" hidden></div><button class="button" type="submit" disabled>Send cleanup request</button><noscript><p>Online submission requires JavaScript. Please call '+PHONE+' to request cleanup.</p></noscript></form><aside class="form-side"><h2>A little information.<br>A clearer next step.</h2><p>Have a close deadline or an active fine? Call us to discuss cleanup availability.</p><p class="phone">'+PHONE+'</p><hr><h3>What happens next</h3><ol><li>We review your property details.</li><li>We contact you about scope and availability.</li><li>You confirm the work before it is scheduled.</li></ol><hr><p>Keep your notice and contact the assigned officer directly for extensions, hearing questions or case status.</p></aside></div>'
page('/fix-my-violation/','Request Overgrown-Property Cleanup in Tampa Bay','Share your property address, code notice and compliance deadline. Request overgrown-lot mowing, brush clearing or debris removal in Tampa Bay.',intro('Let’s get your property cleared.','Tell us about the property and the notice. If your deadline is close, call 813-671-2757 to discuss availability.','Request cleanup').replace('call 813-671-2757','call '+PHONE)+form)
page('/thank-you/','Your Cleanup Request: Next Steps','What happens after a cleanup request, and what to send your code officer once the property is cleared.','<section class="section"><div class="wrap narrow"><p class="eyebrow">Your next steps</p><h1 data-confirmation-title>What happens after you request help.</h1><p class="lead" data-confirmation>If you submitted a request, keep your notice handy. Need to confirm receipt? Call '+PHONE+'.</p><h2>Keep the deadline on your calendar.</h2><p>An online request is not a confirmed booking. We’ll discuss the scope and availability before scheduling. Ask the issuing officer directly about an extension if one is needed; do not assume the date has changed.</p><h2>Have these details ready.</h2><ul><li>The complete notice and case/citation number.</li><li>Property address, access instructions and any known hazards.</li><li>Compliance deadline and hearing date.</li><li>Areas and conditions the officer says must be corrected.</li></ul><h2>After the cleanup, send the officer:</h2><ul><li>Dated before-and-after photos showing every cited area.</li><li>The cleanup invoice and completion date.</li><li>Your address and case number.</li><li>A request for reinspection and written confirmation of compliance.</li></ul><p>Ask whether any fines, lien, hearing or other violation remains. Keep the written response with your records.</p><a class="button secondary" href="/guides/proving-compliance/">View the compliance checklist ↗</a></div></section>',noindex=True)
page('/privacy/','Privacy & Cleanup Request Information','Learn what the Fix My Violation request form collects, how Web3Forms processes submissions, and how to contact us about your information.',intro('Your cleanup request information.','This page describes the information used by this website and its request form.','Privacy')+'<section class="section"><div class="wrap narrow article-content"><h2>What the form collects</h2><p>The form asks for contact details, the property address, jurisdiction, notice information and any details you choose to provide. Email is optional. The form does not accept file uploads. Do not include Social Security numbers, financial account information or other unnecessary sensitive information.</p><h2>What it is used for</h2><p>Your submission is a request for contact about property cleanup, including scope, access and availability. It is not a submission to a government agency. Contact us at '+PHONE+' for questions about the information you sent or to request a correction or deletion.</p><h2>Service providers</h2><p>When enabled, forms are sent over HTTPS to <a href="https://web3forms.com/privacy">Web3Forms</a>, which processes and delivers the request to the business. The site uses Cloudflare hosting; the hosting provider may process technical request information such as IP addresses for delivery and security. Provider policies and retention practices apply to their systems.</p><h2>Browser storage and analytics</h2><p>The site uses session storage for campaign parameters, the first page visited and a short-lived submission confirmation marker. The form code does not save your entered contact details in browser storage. Session storage normally ends when the tab’s session ends. No advertising cookies or analytics beacon are included in this release.</p><p>Last updated October 7, 2026. If analytics or processing practices change, this page should be updated before those changes are enabled.</p></div></section>')
page('/404.html','Page Not Found','This page may have moved. Find Tampa Bay code violation guides or request overgrown-property cleanup.','<section class="error-page wrap"><p class="error-code">404</p><h1>This path needs clearing.</h1><p>The page you’re looking for isn’t here. Find your next step in the <a href="/guides/">owner guides</a>, or tell us about your property.</p>'+CTA+'<p><a href="/">Back to the homepage</a></p></section>',noindex=True)
